297	/** Loads sheets by id; a sheet never loaded before is started empty. */
298	@Service
299	public class SheetService {
300	
301	    private final SheetRepository sheets;
302	    private final Rollup rollup;
303	    private final Audit audit;
304	
305	    public SheetService(SheetRepository sheets, Rollup rollup, Audit audit) {
306	        this.sheets = sheets;
307	        this.rollup = rollup;
308	        this.audit = audit;
309	    }
310	
311	    /** The sheet with this id, re-read from the store; started empty if it has never been loaded. */
312	    @Transactional
313	    public Sheet load(String id, String user) {
314	        return sheets.findById(id).orElseGet(() -> {
315	            try {
316	                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
317	            } catch (DataIntegrityViolationException raced) {
318	                // Another user started the same sheet at the same moment: theirs stands.
319	                return sheets.findById(id).orElseThrow(() -> raced);
320	            }
321	        });
322	    }
323	
324	    /** The sheet's today, or null for a sheet never loaded. */
325	    @Transactional(readOnly = true)
326	    public LocalDate today(String id) {
327	        return sheets.findById(id).map(Sheet::getToday).orElse(null);
328	    }
329	
330	    /** Set the sheet's today, starting the sheet if it has never been loaded. */
331	    @Transactional
332	    public Sheet setToday(String id, String user, LocalDate today) {
333	        Sheet sheet = load(id, user);
334	        Rollup.Figures before = rollup.of(id);
335	        sheet.setToday(today);
336	        Sheet saved = sheets.saveAndFlush(sheet);
337	        rollup.recordChanges(id, user, before);
338	        return saved;
339	    }
340	
341	    /** Set the sheet's clerk limit (null: no limit), starting the sheet if it has never been loaded. */
342	    @Transactional
343	    public Sheet setClerkLimit(String id, String user, BigDecimal limit) {
344	        load(id, user);
345	        Sheet sheet = sheets.findLockedById(id).orElseThrow();
346	        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.UNNECESSARY);
347	        sheet.setClerkLimit(scaled);
348	        Sheet saved = sheets.saveAndFlush(sheet);
349	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user
350	                + " key=clerk-limit value=" + (scaled == null ? "" : scaled.toPlainString()));
351	        return saved;
352	    }
353	
354	    /** Set the sheet's floor, starting the sheet if it has never been loaded. */
355	    @Transactional
356	    public Sheet setFloor(String id, String user, BigDecimal floor) {
357	        load(id, user);
358	        Sheet sheet = sheets.findLockedById(id).orElseThrow();
359	        Rollup.Figures before = rollup.of(id);
360	        BigDecimal scaled = floor.setScale(2, RoundingMode.UNNECESSARY);
361	        sheet.setFloor(scaled);
362	        Sheet saved = sheets.saveAndFlush(sheet);
363	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user
364	                + " key=floor value=" + scaled.toPlainString());
365	        rollup.recordChanges(id, user, before);
366	        return saved;
367	    }
368	
369	    /** Set the sheet's terms in days, starting the sheet if it has never been loaded. */
370	    @Transactional
371	    public Sheet setTerms(String id, String user, int terms) {
372	        load(id, user);
373	        Sheet sheet = sheets.findLockedById(id).orElseThrow();
374	        sheet.setTerms(terms);
375	        Sheet saved = sheets.saveAndFlush(sheet);
376	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=terms value=" + terms);
377	        return saved;
378	    }
379	
380	    /** Set the sheet's late percent, starting the sheet if it has never been loaded. */
381	    @Transactional
382	    public Sheet setLatePct(String id, String user, BigDecimal latePct) {
383	        load(id, user);
384	        Sheet sheet = sheets.findLockedById(id).orElseThrow();
385	        Rollup.Figures before = rollup.of(id);
386	        BigDecimal scaled = latePct.setScale(2, RoundingMode.UNNECESSARY);
387	        sheet.setLatePct(scaled);
388	        Sheet saved = sheets.saveAndFlush(sheet);
389	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user
390	                + " key=late-pct value=" + scaled.toPlainString());
391	        rollup.recordChanges(id, user, before);
392	        return saved;
393	    }
394	
395	    /** Set the sheet's policy date (null: the sheet's today), starting the sheet if it has never been loaded. */
396	    @Transactional
397	    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
398	        load(id, user);
399	        Sheet sheet = sheets.findLockedById(id).orElseThrow();
400	        Rollup.Figures before = rollup.of(id);
401	        sheet.setPolicyDate(policyDate);
402	        Sheet saved = sheets.saveAndFlush(sheet);
403	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user
404	                + " key=policy-date value=" + (policyDate == null ? "" : policyDate));
405	        rollup.recordChanges(id, user, before);
406	        return saved;
407	    }
408	}
