537	          this.resetSettings(sheet);
538	          return this.roles.load(sheet?.id ?? null) ?? EMPTY;
539	        }),
540	        takeUntilDestroyed(),
541	      )
542	      .subscribe({ error: () => this.roleError.set('Could not read the roles.') });
543	    // An error is removed as soon as its form is changed.
544	    this.settingsForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.settingsError.set(null));
545	    this.roleForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.roleError.set(null));
546	  }
547	
548	  protected saveSettings(): void {
549	    // A second submit before the first has answered is ignored, so it stores one change.
550	    if (this.savingSettings()) return;
551	    this.settingsError.set(null);
552	    const sheet = this.sheets.current();
553	    if (!sheet) return;
554	    const { clerkLimit, floor, terms, latePct, policyDate } = this.settingsForm.controls;
555	    const limit = clerkLimit.value.trim();
556	    const floorValue = floor.value.trim();
557	    const termsValue = terms.value.trim();
558	    const latePctValue = latePct.value.trim();
559	    const policyDateValue = policyDate.value.trim();
560	    // Only the settings changed in the form are saved; with none changed, the clerk limit is saved as it is.
561	    const saveFloor = floor.dirty;
562	    const saveTerms = terms.dirty;
563	    const saveLatePct = latePct.dirty;
564	    const savePolicyDate = policyDate.dirty;
565	    const saveLimit = clerkLimit.dirty || (!saveFloor && !saveTerms && !saveLatePct && !savePolicyDate);
566	    if (saveLimit && limit !== '' && !LIMIT_PATTERN.test(limit)) {
567	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
568	      return;
569	    }
570	    if (saveFloor && !LIMIT_PATTERN.test(floorValue)) {
571	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
572	      return;
573	    }
574	    if (saveTerms && !TERMS_PATTERN.test(termsValue)) {
575	      this.settingsError.set('Type terms of 0 or more whole days.');
576	      return;
577	    }
578	    if (saveLatePct && !LATE_PCT_PATTERN.test(latePctValue)) {
579	      this.settingsError.set('Type a late percent of 0.00 or more, up to 999.99, with up to two decimals.');
580	      return;
581	    }
582	    if (savePolicyDate && policyDateValue !== '' && !(DATE_PATTERN.test(policyDateValue) && isDate(policyDateValue))) {
583	      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
584	      return;
585	    }
586	    const saves: Observable<SheetView>[] = [];
587	    if (saveLimit) saves.push(this.sheets.setSettings(sheet.id, limit === '' ? null : limit));
588	    if (saveFloor) saves.push(this.sheets.setFloor(sheet.id, floorValue));
589	    if (saveTerms) saves.push(this.sheets.setTerms(sheet.id, Number(termsValue)));
590	    if (saveLatePct) saves.push(this.sheets.setLatePct(sheet.id, latePctValue));
591	    if (savePolicyDate) saves.push(this.sheets.setPolicyDate(sheet.id, policyDateValue === '' ? null : policyDateValue));
592	    this.savingSettings.set(true);
593	    concat(...saves).pipe(last()).subscribe({
594	      next: (saved) => {
595	        this.savingSettings.set(false);
596	        this.resetSettings(saved);
597	      },
598	      error: () => {
599	        this.savingSettings.set(false);
600	        this.settingsError.set('Could not save the settings.');
601	      },
602	    });
603	  }
604	
605	  /** Show the sheet's settings in the form, as not yet changed. */
606	  private resetSettings(sheet: SheetView | null): void {
607	    this.settingsForm.reset({ clerkLimit: sheet?.clerkLimit ?? '', floor: sheet?.floor ?? '', terms: String(sheet?.terms ?? ''), latePct: sheet?.latePct ?? '', policyDate: sheet?.policyDate ?? '' }, { emitEvent: false });
608	  }
609	
610	  protected saveRole(): void {
611	    // A second submit before the first has answered is ignored, so it stores one record.
612	    if (this.savingRole()) return;
613	    this.roleError.set(null);
614	    const sheet = this.sheets.current();
615	    if (!sheet) return;
616	    const user = this.roleForm.controls.user.value.trim();
617	    const role = this.roleForm.controls.role.value.trim();
618	    if (!user) {
619	      this.roleError.set('Type the user name to assign a role to.');
620	      return;
621	    }
622	    if (!(ROLES as readonly string[]).includes(role)) {
623	      this.roleError.set(`Choose a role: ${this.roleNames}.`);
624	      return;
625	    }
626	    this.savingRole.set(true);
627	    this.roles.set(sheet.id, user, role as RoleName).subscribe({
628	      next: () => {
629	        this.savingRole.set(false);
630	        this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
631	      },
632	      error: () => {
633	        this.savingRole.set(false);
634	        this.roleError.set('Could not assign that role.');
635	      },
636	    });
637	  }
638	}
639	import { HttpClient } from '@angular/common/http';
640	import { Injectable, inject, signal } from '@angular/core';
641	import { Observable, tap } from 'rxjs';
642	
643	export interface SheetView {
644	  id: string;
645	  /** The sheet's today (yyyy-mm-dd): every date-dependent decision and default uses it, never the clock. */
646	  today: string;
647	  /** A clerk can settle a claim only when its due is at or below this (two decimals); null: no limit. */
648	  clerkLimit: string | null;
649	  /** A claim's live due is at least this (two decimals). */
650	  floor: string;
651	  /** The sheet's terms in days: a claim is due by its date plus these. */
652	  terms: number;
653	  /** The sheet's late percent (two decimals): an overdue claim's due gains this percent of its figure
654	   *  for every full 30 days it is overdue. */
655	  latePct: string;
656	  /** The sheet's policy date (yyyy-mm-dd): a claim dated before it rounds half up, one on or after it half to
657	   *  even; null when it is the sheet's today. */
658	  policyDate: string | null;
659	}
660	
661	/** The terms a sheet has until they are changed. */
662	export const DEFAULT_TERMS = 14;
663	
664	// The active sheet. Everything else in the app is kept per sheet; loading an id re-reads it from
665	// the store, and an id never loaded before starts an empty sheet.
666	@Injectable({ providedIn: 'root' })
667	export class Sheets {
668	  private readonly http = inject(HttpClient);
669	  private readonly active = signal<SheetView | null>(null);
670	  readonly current = this.active.asReadonly();
671	  /** The sheet as last (re)loaded: set on each load only, so changing its today re-reads nothing. */
672	  private readonly lastLoad = signal<SheetView | null>(null);
673	  readonly loaded = this.lastLoad.asReadonly();
674	
675	  load(id: string): Observable<SheetView> {
676	    return this.http
677	      .post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null)
678	      .pipe(
679	        tap((s) => {
680	          this.active.set(s);
681	          this.lastLoad.set(s);
682	        }),
683	      );
684	  }
685	
686	  /** Change the active sheet's today. */
687	  setToday(id: string, today: string): Observable<SheetView> {
688	    return this.http
689	      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today })
690	      .pipe(tap((s) => this.active.set(s)));
691	  }
692	
693	  /** Change the active sheet's settings; a null clerk limit means no limit. */
694	  setSettings(id: string, clerkLimit: string | null): Observable<SheetView> {
695	    return this.http
696	      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings`, { clerkLimit })
697	      .pipe(tap((s) => this.active.set(s)));
698	  }
699	
700	  /** Change the active sheet's floor. */
701	  setFloor(id: string, floor: string): Observable<SheetView> {
702	    return this.http
703	      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/floor`, { floor })
704	      .pipe(tap((s) => this.active.set(s)));
705	  }
706	
707	  /** Change the active sheet's terms (days). */
708	  setTerms(id: string, terms: number): Observable<SheetView> {
709	    return this.http
710	      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/terms`, { terms })
711	      .pipe(tap((s) => this.active.set(s)));
712	  }
713	
714	  /** Change the active sheet's policy date; null means the sheet's today. */
715	  setPolicyDate(id: string, policyDate: string | null): Observable<SheetView> {
716	    return this.http
717	      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/policy-date`, { policyDate })
718	      .pipe(tap((s) => this.active.set(s)));
719	  }
720	
721	  /** Change the active sheet's late percent. */
